require_once __DIR__ . '/blocks.php';
function sy3_home_content(): string {
    $contact = 'https://t.me/moi_imperator';
    $hero = sy3_g(sy3_cols([
        sy3_p('<span class="status-dot" aria-hidden="true"></span> АВТОМАТИЗАЦИЯ БИЗНЕСА', 'eyebrow') .
        sy3_h('Ваш бизнес.<br>Меньше рутины.<br><em>Больше порядка.</em>', 1) .
        sy3_p('Создаю сайты и веб-сервисы, настраиваю CRM и связываю рабочие инструменты. Чтобы клиенту было удобно обратиться, а команде — принять заявку и выполнить работу.', 'hero-intro') .
        sy3_buttons([['Обсудить мой процесс ↗', $contact], ['Посмотреть проекты ↓', '#selected-cases', true]]) .
        sy3_p('Напишите Артёму в Telegram. Начнём с вашей задачи — без готового ТЗ.', 'hero-note'),
        sy3_image('hero-system.webp', 'Связанные элементы одной системы для работы бизнеса.', 'hero-art') . sy3_p('САЙТЫ И СЕРВИСЫ <span>↔</span> CRM <span>↔</span> ИИ', 'hero-art-caption')
    ], 'hero-columns') . sy3_g(
        sy3_p('<strong class="bitrix">Битрикс24</strong><br>Бизнес-партнёр') .
        sy3_p('<strong>От заявки до работы</strong><br>Проверяю весь путь') .
        sy3_p('<strong>Ваши сервисы</strong><br>Настраиваю и связываю') .
        sy3_p('<strong>Артём Суязов</strong><br>Лично разбираю вашу задачу'),
        'trust-strip'
    ), 'section-inner');
    $services = sy3_p('01 / Решения для бизнеса', 'eyebrow') . sy3_g(sy3_h('Сайты и автоматизация<br>для работы бизнеса.') . sy3_p('<a class="text-link" href="' . esc_url(home_url('/services/')) . '">Все направления ↗</a>'), 'section-heading') . sy3_shortcode('[sy3_cards type="sy3_service" count="4"]');
    $cases = sy3_p('02 / Выбранные проекты', 'eyebrow') . sy3_g(sy3_h('<span id="selected-cases">Работа, которую<br>можно посмотреть.</span>') . sy3_p('<a class="text-link" href="' . esc_url(home_url('/cases/')) . '">Все 25 кейсов ↗</a>'), 'section-heading') . sy3_shortcode('[sy3_featured_cases]');
    $process = sy3_p('03 / Как работаем', 'eyebrow') . sy3_h('Автоматизация начинается<br>с разговора о работе.') . sy3_p('Согласуем понятный результат и способ проверки до начала внедрения.', 'section-intro') . sy3_cols([
        sy3_p('01 / РАЗОБРАТЬСЯ', 'step-number') . sy3_h('Увидеть процесс', 3) . sy3_p('Собираем путь заявки, участников, системы и ручные операции. Находим узкое место.'),
        sy3_p('02 / ДОГОВОРИТЬСЯ', 'step-number') . sy3_h('Выбрать первый шаг', 3) . sy3_p('Определяем границы работ, ограничения, стоимость и сценарий приёмки.'),
        sy3_p('03 / СДЕЛАТЬ', 'step-number') . sy3_h('Собрать решение', 3) . sy3_p('Разрабатываем сайт или сервис, настраиваем CRM и интеграции. Для ИИ начинаем с ограниченного пилота.'),
        sy3_p('04 / ПРОВЕРИТЬ', 'step-number') . sy3_h('Пройти весь путь', 3) . sy3_p('Проверяем рабочий сценарий, передаём инструкции и договариваемся о сопровождении.')
    ], 'process-grid');
    $author = sy3_cols([
        sy3_p('Лично отвечаю<br>за проект.', 'author-statement') . sy3_p('Артём Суязов<br><span>IT-бизнес-партнёр</span>', 'author-name'),
        sy3_p('04 / Кто отвечает за работу', 'eyebrow') . sy3_h('Привет,<br>я Артём Суязов.') . sy3_p('Работаю на стыке бизнеса и технологий: разбираю процессы, связываю системы и помогаю довести изменения до рабочего сценария.') . sy3_p('Мне важно, чтобы после проекта было понятно, как пользоваться решением, кто за него отвечает и как проверить, что оно работает.') . sy3_p('<a class="text-link" href="' . esc_url(home_url('/about/')) . '">Подробнее о подходе ↗</a>') . sy3_p('Лично веду разбор задачи и согласование решения.', 'author-signature')
    ], 'author-grid');
    $journal = sy3_p('05 / Журнал', 'eyebrow') . sy3_g(sy3_h('Разобраться.<br>Принять решение.') . sy3_p('<a class="text-link" href="' . esc_url(home_url('/journal/')) . '">Читать журнал ↗</a>'), 'section-heading') . sy3_p('Практические разборы для собственника: что проверить, с чего начать и как принять работу.', 'section-intro') . sy3_shortcode('[sy3_cards type="post" count="3"]');
    $faq = sy3_p('06 / Частые вопросы', 'eyebrow') . sy3_h('До начала работы') . sy3_g(
        sy3_faq('У нас уже есть CRM. Обязательно менять?', 'Сначала разбираем текущую систему и процесс. Часто можно настроить работу, исправить интеграцию или убрать лишние ручные операции. Замена CRM обсуждается только при понятных причинах.') .
        sy3_faq('Можно начать с небольшой задачи?', 'Да. Например, проверить путь заявки с сайта до CRM, связать два сервиса или собрать один сценарий автоматизации. У первого этапа должны быть конкретные границы и критерий готовности.') .
        sy3_faq('Сколько стоит внедрение?', 'Стоимость зависит от текущей системы, числа процессов, интеграций и состояния данных. После разбора согласуем состав первого этапа и стоимость. Лицензии и платные сервисы обсуждаются отдельно.') .
        sy3_faq('Можно сразу отдать процесс искусственному интеллекту?', 'Для сценариев с ценой ошибки сначала нужен пилот и контроль человека. Заранее определяем допустимые данные, критерии ответа и действия при ошибке. Не каждый процесс нужно автоматизировать с помощью ИИ.'), 'faq-list');
    $cta = sy3_cols([
        sy3_p('Начнём с одной задачи', 'eyebrow') . sy3_h('Что сейчас<br>тормозит<br>ваш бизнес?'),
        sy3_p('Расскажите, где теряются заявки или время команды. Я уточню детали и предложу первый этап: что сделать, сколько это стоит и как проверить результат.') . sy3_buttons([['Написать Артёму ↗', $contact]]) . sy3_p('<a href="tel:+79064790552">+7 (906) 479-05-52</a>', 'contact-alternative')
    ], 'cta-panel');
    return sy3_g($hero, 'hero hero-redesign', 'section') . sy3_section($services, 'services-section') . sy3_section($cases, 'work-section') . sy3_section($process, 'section-dark') . sy3_section($author, 'author-section') . sy3_section($journal, 'journal-section') . sy3_section($faq) . sy3_section($cta, 'contact-section');
}

function sy3_personal_home(): string {
    $main = rtrim(get_option('sy3_main_url', 'https://sy3.ru'), '/');
    $hero = sy3_g(sy3_cols([
        sy3_p('Артём Суязов / IT-бизнес-партнёр', 'eyebrow') . sy3_h('На стороне<br>бизнеса.<br><em>На языке IT.</em>', 1) . sy3_p('Разбираюсь в процессах, связываю системы и довожу решения до работы. CRM, интеграции и ИИ — с понятной целью.', 'hero-intro') . sy3_buttons([['Обсудить сотрудничество ↗', home_url('/contacts/')], ['Мои работы ↗', home_url('/portfolio/'), true]]) . sy3_p('Проектные задачи и постоянное участие в развитии IT.', 'hero-note'),
        sy3_shortcode('[sy3_visual mode="personal"]')
    ], 'hero-columns'), 'section-inner');
    $scope = sy3_p('01 / Чем могу быть полезен', 'eyebrow') . sy3_h('Связать задачу бизнеса<br>с работающим решением.') . sy3_cols([
        sy3_h('Разобраться', 3) . sy3_p('Собрать картину текущих систем и процессов. Понять, почему работа буксует и что менять первым.'),
        sy3_h('Довести до работы', 3) . sy3_p('Согласовать первый этап, собрать решение и проверить полный сценарий вместе с командой.'),
        sy3_h('Развивать дальше', 3) . sy3_p('Поддерживать систему, разбирать новые задачи и сохранять понятную документацию решений.')
    ], 'problem-grid');
    $works = sy3_p('02 / Выбранные работы', 'eyebrow') . sy3_h('Опыт — в деталях проектов.') . sy3_p('Подробные кейсы собраны на основном сайте Сутри: там описаны задача, работа и границы подтверждённого результата.', 'section-intro') . sy3_shortcode('[sy3_external_cases]');
    $approach = sy3_p('03 / Мой подход', 'eyebrow') . sy3_h('Понятность —<br>часть результата.') . sy3_p('В работе мне важны три вопроса: какую проблему решаем, кто будет пользоваться решением и как мы поймём, что задача выполнена.', 'section-intro') . sy3_cols([
        sy3_p('01', 'step-number') . sy3_h('Задача раньше инструмента', 3) . sy3_p('Сначала процесс и ограничения. Затем выбор CRM, интеграции или ИИ.'),
        sy3_p('02', 'step-number') . sy3_h('У первого этапа есть границы', 3) . sy3_p('Согласуем объём, критерии готовности и вопросы, которые остаются за рамками.'),
        sy3_p('03', 'step-number') . sy3_h('Проверка на вашем сценарии', 3) . sy3_p('Проверяем путь пользователя, а не только отдельную настройку.'),
        sy3_p('04', 'step-number') . sy3_h('Знания остаются у команды', 3) . sy3_p('Передаём инструкции, решения и понятный следующий шаг.')
    ], 'process-grid');
    $links = sy3_p('04 / Услуги и материалы', 'eyebrow') . sy3_h('Больше практики — на Сутри.') . sy3_p('Подробные направления работы, кейсы и экспертный журнал находятся на одном основном сайте. Здесь — мой подход и возможность обсудить сотрудничество.', 'section-intro') . sy3_buttons([['Услуги и кейсы ↗', $main . '/'], ['Читать журнал ↗', $main . '/journal/', true]]);
    $cta = sy3_cols([sy3_h('Нужен человек,<br>который разберётся?'), sy3_p('Расскажите о бизнесе, текущих системах и задаче. Обсудим, какой формат работы подойдёт.') . sy3_buttons([['Написать Артёму ↗', home_url('/contacts/')]])], 'cta-panel');
    return sy3_g($hero, 'hero', 'section') . sy3_section($scope) . sy3_section($works, 'section-tint') . sy3_section($approach, 'section-dark') . sy3_section($links) . sy3_section($cta);
}
